use super::*;
use self::core::wire::Capability;
use std::sync::Arc;
thread_local!{pub(super) static FAULT:std::cell::RefCell<Option<String>>=const{std::cell::RefCell::new(None)};pub(super) static PAGES:std::cell::Cell<Option<i64>>=const{std::cell::Cell::new(None)};}
struct Qa{root:PathBuf,repo:Repository,time:Arc<Mutex<String>>}
impl Qa{
    fn new()->Self{let root=std::env::temp_dir().join("opencode").join(format!("5d3b1-{}",uuid::Uuid::new_v4()));let time=Arc::new(Mutex::new("2026-10-26T12:00:00Z".into()));let mut repo=Repository::new(root.clone(),Policy::qa());repo.clock=Clock{fixed:Some(time.clone())};Self{root,repo,time}}
    fn init()->Self{let q=Self::new();q.repo.initialize_new().unwrap();q}
    fn ready()->Self{let q=Self::init();q.repo.accept_trust_episode(&id(),0,&[fixture("trust1")]).unwrap();q}
    fn installed()->Self{let q=Self::ready();q.repo.record_verified_installation(&id(),1,&fixture("package1"),&[Capability::Direct,Capability::Inverse]).unwrap();q}
    fn now(&self,s:&str){*self.time.lock().unwrap()=s.into();}
    fn sql(&self)->Connection{schema::open(&self.repo.db(),false).unwrap()}
}
impl Drop for Qa{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
fn id()->String{uuid::Uuid::new_v4().to_string()}
fn fixture(name:&str)->Vec<u8>{let p=Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b1/fixtures").join(format!("{name}.json"));fs::read(p).unwrap()}
fn error<T>(r:Result<T>,code:&str){match r{Err(e)=>assert_eq!(e.code,code,"{e:?}"),Ok(_)=>panic!("Expected {code}")}}
fn evidence(name:&str,value:serde_json::Value){let folder=Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b1/windows");fs::create_dir_all(&folder).unwrap();fs::write(folder.join(format!("{name}.json")),serde_json::to_vec_pretty(&value).unwrap()).unwrap();}
#[test]fn new_repository_has_no_selection_or_authorization(){let q=Qa::new();assert_eq!(q.repo.inspect_presence().unwrap(),"absent");let s=q.repo.initialize_new().unwrap();assert_eq!(s.generation,0);assert_eq!(s.sqlite_version,"3.51.1");assert_eq!(s.validity,"metadata-required");let c=q.sql();for t in ["installations","admissions","selection_events","rollback_uses"]{assert_eq!(count(&c,t).unwrap(),0);}error(q.repo.initialize_new(),"INITIALIZATION_NOT_ALLOWED");}
#[test]fn original_bytes_reopen_and_nonexecutable_admission(){let q=Qa::installed();let bytes=fixture("package1");let h=core::hashes::sha256(&bytes);assert_eq!(q.repo.read_original(&h).unwrap(),bytes);let mut reopened=Repository::new(q.root.clone(),Policy::qa());reopened.clock=q.repo.clock.clone();assert_eq!(reopened.open_existing().unwrap().generation,2);assert_eq!(reopened.read_original(&h).unwrap(),bytes);let c=q.sql();assert_eq!(c.query_row("SELECT state FROM admissions",[],|r|r.get::<_,String>(0)).unwrap(),"recorded-not-executable");assert_eq!(count(&c,"selection_events").unwrap(),0);}
#[test]fn immutable_objects_cannot_be_updated_or_deleted(){let q=Qa::installed();let c=q.sql();for table in ["content_objects","signed_payloads","containers","trust_documents","operations"]{assert!(c.execute(&format!("DELETE FROM {table}"),[]).is_err());let col=if table=="operations"{"body"}else{"bytes"};assert!(c.execute(&format!("UPDATE {table} SET {col}=x'00'"),[]).is_err());}}
