fn child_process(root:&Path,mode:&str,stop:&str,operation:&str)->std::process::Child{std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","fiscal_repository::tests::native_child","--ignored","--nocapture"]).env("NOMINA_FISCAL_ROOT",root).env("NOMINA_FISCAL_MODE",mode).env("NOMINA_FISCAL_STOP",stop).env("NOMINA_FISCAL_OPERATION",operation).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).spawn().unwrap()}
fn wait_point(child:&mut std::process::Child,point:&str){use std::io::BufRead;let stdout=child.stdout.take().unwrap();for line in std::io::BufReader::new(stdout).lines(){let line=line.unwrap();if line.contains(&format!("FISCAL_READY:{point}")){return;}}panic!("Child did not reach {point}");}
#[test]fn initialization_external_kill_at_every_protocol_boundary(){
    let mut records=vec![];
    for point in ["initialization-before-intention","initialization-partial-intention","initialization-intention","initialization-reserved","initialization-schema","initialization-before-commit","initialization-after-commit","initialization-verifying","initialization-before-complete","initialization-partial-complete","initialization-complete"]{
        let q=Qa::new();let mut child=child_process(&q.root,"initialize",point,&id());wait_point(&mut child,point);child.kill().unwrap();child.wait().unwrap();
        match point{
            "initialization-before-intention"=>{assert_eq!(q.repo.inspect_presence().unwrap(),"absent");q.repo.initialize_new().unwrap();},
            "initialization-after-commit"|"initialization-verifying"|"initialization-before-complete"=>{assert_eq!(q.repo.recover_initialization().unwrap().generation,0);},
            "initialization-complete"=>{assert_eq!(q.repo.open_existing().unwrap().generation,0);},
            _=>{assert!(q.repo.initialize_new().is_err());assert!(q.repo.recover_initialization().is_err());assert!(q.repo.open_existing().is_err());}
        }
        records.push(serde_json::json!({"point":point,"terminatedExternally":true,"safe":true}));
    }
    evidence("initialization-crashes",serde_json::json!({"status":"passed","cases":records}));
}
#[test]fn operation_external_kill_before_and_after_commit(){let mut records=vec![];for point in ["operation-before-commit","operation-after-commit"]{let q=Qa::ready();let op=id();let mut child=child_process(&q.root,"install",point,&op);wait_point(&mut child,point);child.kill().unwrap();child.wait().unwrap();let committed=point=="operation-after-commit";let generation=q.repo.open_existing().unwrap().generation;assert_eq!(generation,if committed{2}else{1});assert_eq!(q.repo.operation_status(&op).unwrap().is_some(),committed);let receipt=q.repo.record_verified_installation(&op,1,&fixture("package1"),&[Capability::Direct]).unwrap();assert_eq!(receipt.generation,2);assert_eq!(q.repo.open_existing().unwrap().installations,1);records.push(serde_json::json!({"point":point,"generationAfterKill":generation,"committed":committed,"afterRetry":2,"installations":1}));}evidence("operation-crashes",serde_json::json!({"status":"passed","cases":records}));}
#[test]fn two_windows_processes_initialize_without_two_repositories(){let q=Qa::new();let a=child_process(&q.root,"initialize","",&id());let b=child_process(&q.root,"initialize","",&id());let a=a.wait_with_output().unwrap();let b=b.wait_with_output().unwrap();assert!(a.status.success()&&b.status.success(),"{:?} {:?}",a.stderr,b.stderr);assert_eq!(q.repo.open_existing().unwrap().generation,0);}
#[test]fn two_windows_processes_retry_the_same_operation_id(){let q=Qa::ready();let op=id();let a=child_process(&q.root,"install","",&op);let b=child_process(&q.root,"install","",&op);let a=a.wait_with_output().unwrap();let b=b.wait_with_output().unwrap();assert!(a.status.success()&&b.status.success(),"{:?} {:?}",a.stderr,b.stderr);assert_eq!(q.repo.open_existing().unwrap().generation,2);assert_eq!(q.repo.open_existing().unwrap().installations,1);evidence("two-process-idempotence",serde_json::json!({"status":"passed","windowsProcesses":2,"successfulExitCodes":[a.status.code(),b.status.code()],"generation":2,"installations":1}));}
#[test]fn two_windows_processes_cannot_lose_an_update(){let q=Qa::ready();let a=child_process(&q.root,"install","",&id());let b=child_process(&q.root,"install","",&id());let a=a.wait_with_output().unwrap();let b=b.wait_with_output().unwrap();assert!(a.status.success()&&b.status.success());let text=format!("{}{}",String::from_utf8_lossy(&a.stdout),String::from_utf8_lossy(&b.stdout));assert!(text.contains("STALE_GENERATION"));assert_eq!(q.repo.open_existing().unwrap().generation,2);}
#[cfg(windows)]#[test]fn lock_cannot_be_unlinked_and_os_releases_it_after_kill(){let q=Qa::installed();let mut child=child_process(&q.root,"lock","held",&id());wait_point(&mut child,"held");assert!(fs::remove_file(q.root.join(".fiscal-maintenance.lock")).is_err());error(q.repo.open_existing(),"BUSY");child.kill().unwrap();child.wait().unwrap();assert_eq!(q.repo.open_existing().unwrap().generation,2);}
#[test]#[ignore="Native child helper, invoked by passing process tests"]fn native_child(){let root=PathBuf::from(std::env::var_os("NOMINA_FISCAL_ROOT").unwrap());assert!(root.starts_with(std::env::temp_dir().join("opencode")));assert!(root.file_name().unwrap().to_string_lossy().starts_with("5d3b1-"));let mut r=Repository::new(root,Policy::qa());r.clock=Clock{fixed:Some(Arc::new(Mutex::new("2026-10-26T12:00:00Z".into())))};let mode=std::env::var("NOMINA_FISCAL_MODE").unwrap();let op=std::env::var("NOMINA_FISCAL_OPERATION").unwrap();match mode.as_str(){"initialize"=>match r.initialize_new(){Ok(s)=>println!("{}",serde_json::to_string(&s).unwrap()),Err(e) if e.code=="INITIALIZATION_NOT_ALLOWED"=>println!("ALREADY_INITIALIZED"),Err(e)=>panic!("{e:?}")},"install"=>match r.record_verified_installation(&op,1,&fixture("package1"),&[Capability::Direct]){Ok(v)=>println!("{}",serde_json::to_string(&v).unwrap()),Err(e) if e.code=="STALE_GENERATION"=>println!("STALE_GENERATION"),Err(e)=>panic!("{e:?}")},"lock"=>{let _held=paths::lock(&r.root).unwrap();println!("FISCAL_READY:held");use std::io::Write;std::io::stdout().flush().unwrap();loop{std::thread::park();}},_=>panic!("Unknown QA mode")}}

#[cfg(windows)]#[test]fn real_ntfs_acl_denies_journal_creation_without_changing_state(){
    use std::process::Command;
    let q=Qa::ready();let who=Command::new("whoami").args(["/user","/fo","csv","/nh"]).output().unwrap();assert!(who.status.success());let text=String::from_utf8_lossy(&who.stdout);let sid=text.trim().split(',').next_back().unwrap().trim_matches('"');assert!(sid.starts_with("S-1-"));let target=q.root.join("fiscal");
    struct Restore{path:PathBuf,sid:String}impl Drop for Restore{fn drop(&mut self){let _=Command::new("icacls").arg(&self.path).arg("/remove:d").arg(format!("*{}",self.sid)).output();}}
    let restore=Restore{path:target.clone(),sid:sid.into()};let output=Command::new("icacls").arg(&target).arg("/deny").arg(format!("*{sid}:(W)")).output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
    let native_error=fs::OpenOptions::new().write(true).create_new(true).open(target.join("journal-acl-probe")).unwrap_err();assert_eq!(native_error.raw_os_error(),Some(5));let result=q.repo.record_verified_installation(&id(),1,&fixture("package1"),&[Capability::Direct]);assert!(result.is_err());let code=result.unwrap_err().code;assert_ne!(code,"BUSY");drop(restore);assert_eq!(q.repo.open_existing().unwrap().generation,1);assert_eq!(q.repo.open_existing().unwrap().installations,0);q.repo.record_verified_installation(&id(),1,&fixture("package1"),&[Capability::Direct]).unwrap();evidence("ntfs-acl",serde_json::json!({"status":"passed","realDaclChanged":true,"nativeWin32Error":5,"repositoryError":code,"generationAfterFailure":1,"installationsAfterFailure":0,"retryAfterRestoringAcl":"passed"}));
}

