#[test]fn re_signed_payload_adds_container_not_fiscal_revision(){let mut q=Qa::new();let folder=Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b1/rotation");let b:serde_json::Value=serde_json::from_slice(&fs::read(folder.join("bootstrap.json")).unwrap()).unwrap();q.repo.policy=Policy{channel:"qa".into(),roots:serde_json::from_value(b["rootKeys"].clone()).unwrap()};q.repo.initialize_new().unwrap();q.repo.accept_trust_episode(&id(),0,&[fs::read(folder.join("trust1.json")).unwrap()]).unwrap();q.repo.record_verified_installation(&id(),1,&fs::read(folder.join("package1.json")).unwrap(),&[Capability::Direct]).unwrap();q.repo.accept_trust_episode(&id(),2,&[fs::read(folder.join("trust2.json")).unwrap()]).unwrap();q.repo.record_verified_installation(&id(),3,&fs::read(folder.join("package-resigned.json")).unwrap(),&[Capability::Direct,Capability::Inverse]).unwrap();let c=q.sql();assert_eq!(count(&c,"content_objects").unwrap(),1);assert_eq!(count(&c,"signed_payloads").unwrap(),1);assert_eq!(count(&c,"containers").unwrap(),2);assert_eq!(count(&c,"publications").unwrap(),1);assert_eq!(count(&c,"installations").unwrap(),2);assert_eq!(c.query_row("SELECT revision FROM accepted_heads",[],|r|r.get::<_,i64>(0)).unwrap(),1);}
#[test]fn jcs_and_strict_parser_survive_tauri_feature_unification(){let folder=Path::new(env!("CARGO_MANIFEST_DIR")).join("../crates/nomina-fiscal-package/tests/vectors");let vectors:Vec<serde_json::Value>=serde_json::from_slice(&fs::read(folder.join("jcs.json")).unwrap()).unwrap();for v in vectors{let value:serde_json::Value=serde_json::from_str(v["input"].as_str().unwrap()).unwrap();assert_eq!(core::canonical::bytes(&value).unwrap(),v["output"].as_str().unwrap().as_bytes());}for b in ["-0","1.0","1e0","9007199254740992","{\"a\":1,\"\\u0061\":2}"]{assert!(core::strict_json::parse(b.as_bytes()).is_err());}}
#[test]fn isolated_verification_does_not_advance_any_durable_counter(){let q=Qa::ready();let c=q.sql();let m=paths::marker(&q.root.join("fiscal-initialized.json")).unwrap();let view=replay::rebuild(&c,&Policy::qa(),&m).unwrap();let before=schema::digest(&c).unwrap();let candidate=core::verify_candidate(&fixture("package1"),&view.trust,&core::compatibility::CompiledPolicy::current_2026(),&core::revisions::MemoryRevisions::default(),Capability::Inverse,&q.repo.clock.now().unwrap()).unwrap();assert_eq!(candidate.report().execution,"not-installed-not-authorized");assert_eq!(schema::digest(&c).unwrap(),before);assert_eq!(count(&c,"installations").unwrap(),0);}
#[test]fn salary_shaped_json_is_rejected_without_audit_or_persisted_input_hash(){let q=Qa::ready();let data=b"{\"workerName\":\"qa-private-person\",\"gross\":\"987654321.09\"}";let hash=core::hashes::sha256(data);let before=schema::digest(&q.sql()).unwrap();assert!(q.repo.record_verified_installation(&id(),1,data,&[Capability::Direct]).is_err());assert_eq!(schema::digest(&q.sql()).unwrap(),before);let db=fs::read(q.repo.db()).unwrap();assert!(!db.windows(hash.len()).any(|w|w==hash.as_bytes()));assert!(!db.windows(17).any(|w|w==b"qa-private-person"));}
#[test]fn future_nonce_uniqueness_is_tested_then_rolled_back_without_activation(){let q=Qa::installed();q.repo.record_verified_installation(&id(),2,&fixture("package2"),&[Capability::Direct]).unwrap();let original:serde_json::Value=serde_json::from_slice(&fixture("package1")).unwrap();let target=core::hashes::canonical_hash(&original["signed"]).unwrap();let op=id();q.repo.record_rollback_evidence(&op,3,&fixture("rollback"),&target,2).unwrap();let mut c=q.sql();let tx=c.transaction().unwrap();let installation:String=tx.query_row("SELECT id FROM installations ORDER BY id LIMIT 1",[],|r|r.get(0)).unwrap();let grant=core::hashes::sha256(&fixture("rollback"));let event=id();tx.execute("INSERT INTO selection_events VALUES(?1,?2,?3,'qa-5d3b1-permit-001')",params![event,op,installation]).unwrap();tx.execute("INSERT INTO rollback_uses VALUES('qa-5d3b1-permit-001',?1,?2)",params![grant,event]).unwrap();assert!(tx.execute("INSERT INTO rollback_uses VALUES('qa-5d3b1-permit-001',?1,?2)",params![grant,event]).is_err());tx.rollback().unwrap();assert_eq!(count(&c,"rollback_uses").unwrap(),0);assert_eq!(count(&c,"selection_events").unwrap(),0);assert_eq!(c.query_row("SELECT revision FROM accepted_heads",[],|r|r.get::<_,i64>(0)).unwrap(),2);}

#[cfg(windows)]#[test]#[ignore="Requires explicitly supplied empty QA volume, capacity <=512MiB; not satisfied by SQLite quota"]fn real_full_qa_volume(){
    use std::{io::Write,os::windows::ffi::OsStrExt};
    let volume=PathBuf::from(std::env::var_os("NOMINA_FISCAL_VOLUME_ROOT").expect("User must supply isolated QA volume"));paths::directory(&volume).unwrap();
    for e in fs::read_dir(&volume).unwrap(){let e=e.unwrap();assert!(["System Volume Information","$RECYCLE.BIN"].contains(&e.file_name().to_string_lossy().as_ref()),"QA volume must be empty");}
    let wide:Vec<u16>=volume.as_os_str().encode_wide().chain(Some(0)).collect();let mut free=0;let mut total=0;let mut overall=0;assert_ne!(unsafe{windows_sys::Win32::Storage::FileSystem::GetDiskFreeSpaceExW(wide.as_ptr(),&mut free,&mut total,&mut overall)},0);assert!(total>=16*1024*1024&&total<=512*1024*1024,"Never fill the user's main disk");
    let root=volume.join(format!("5d3b1-{}",uuid::Uuid::new_v4()));let time=Arc::new(Mutex::new("2026-10-26T12:00:00Z".into()));let mut repo=Repository::new(root.clone(),Policy::qa());repo.clock=Clock{fixed:Some(time.clone())};let q=Qa{root,repo,time};q.repo.initialize_new().unwrap();q.repo.accept_trust_episode(&id(),0,&[fixture("trust1")]).unwrap();let before=schema::digest(&q.sql()).unwrap();
    let filler=q.root.join("filler.bin");let mut f=fs::OpenOptions::new().write(true).create_new(true).open(&filler).unwrap();let mut chunk=vec![0u8;1024*1024];let mut x=0x5d3b1u64;for b in &mut chunk{x^=x<<13;x^=x>>7;x^=x<<17;*b=x as u8;}let mut written=0u64;let io_error=loop{match f.write_all(&chunk){Ok(())=>written+=chunk.len() as u64,Err(e)=>break e};assert!(written<=total);};drop(f);assert!(matches!(io_error.raw_os_error(),Some(39)|Some(112)));let op=id();let result=q.repo.record_verified_installation(&op,1,&fixture("package1"),&[Capability::Direct]);assert!(result.is_err());let code=result.unwrap_err().code;fs::remove_file(filler).unwrap();assert_eq!(q.repo.open_existing().unwrap().generation,1);assert_eq!(q.repo.open_existing().unwrap().installations,0);assert_eq!(schema::digest(&q.sql()).unwrap(),before);assert!(q.repo.operation_status(&op).unwrap().is_none());q.repo.record_verified_installation(&op,1,&fixture("package1"),&[Capability::Direct]).unwrap();
    evidence("full-volume",serde_json::json!({"status":"passed","volumeCapacity":total,"bytesWrittenBeforeNativeFull":written,"nativeWin32Error":io_error.raw_os_error(),"repositoryError":code,"logicalStatePreserved":true,"generationAfterFailure":1,"retryAfterFreeingSpace":"passed","sqlitePageQuota":false}));
}
